// Synthesises the app's six UI sounds as small WAV files.
// These are original works generated by this script, dedicated to the public domain (CC0 1.0).
import { writeFileSync, mkdirSync } from 'node:fs';
const SR = 22050;
function wav(samples) {
  const n = samples.length, buf = Buffer.alloc(44 + n * 2);
  buf.write('RIFF', 0); buf.writeUInt32LE(36 + n * 2, 4); buf.write('WAVE', 8); buf.write('fmt ', 12);
  buf.writeUInt32LE(16, 16); buf.writeUInt16LE(1, 20); buf.writeUInt16LE(1, 22); buf.writeUInt32LE(SR, 24);
  buf.writeUInt32LE(SR * 2, 28); buf.writeUInt16LE(2, 32); buf.writeUInt16LE(16, 34); buf.write('data', 36); buf.writeUInt32LE(n * 2, 40);
  for (let i = 0; i < n; i++) buf.writeInt16LE(Math.round(Math.max(-1, Math.min(1, samples[i])) * 32767), 44 + i * 2);
  return buf;
}
function render(dur, fn) { const n = Math.floor(dur * SR), out = new Float32Array(n); for (let i = 0; i < n; i++) out[i] = fn(i / SR); return out; }
const env = (t, a, d) => (t < a ? t / a : Math.exp(-(t - a) / d));
const sine = (f, t) => Math.sin(2 * Math.PI * f * t);
const bell = (f, t, start, d = 0.18) => (t < start ? 0 : env(t - start, 0.004, d) * (sine(f, t - start) * 0.7 + sine(f * 2, t - start) * 0.18 + sine(f * 3.01, t - start) * 0.06));
const sounds = {
  tap: render(0.06, (t) => env(t, 0.002, 0.012) * (sine(1400, t) * 0.5 + sine(2100, t) * 0.2) * 0.5),
  correct: render(0.45, (t) => (bell(1318.5, t, 0, 0.1) + bell(1975.5, t, 0.075, 0.2)) * 0.42), // E6 -> B6 coin chime
  wrong: render(0.28, (t) => env(t, 0.006, 0.07) * (sine(196 - t * 120, t) * 0.8 + sine(294 - t * 160, t) * 0.25) * 0.45), // soft low thud
  complete: render(0.9, (t) => (bell(523.25, t, 0) + bell(659.25, t, 0.09) + bell(783.99, t, 0.18) + bell(1046.5, t, 0.27, 0.35)) * 0.3),
  streak: render(0.6, (t) => env(t, 0.02, 0.18) * sine(440 + 900 * Math.min(t / 0.25, 1) ** 2, t) * 0.32 + bell(1760, t, 0.22, 0.2) * 0.25),
  badge: render(1.1, (t) => (bell(783.99, t, 0, 0.5) + bell(987.77, t, 0.05, 0.5) + bell(1174.66, t, 0.1, 0.5) + bell(1567.98, t, 0.22, 0.45) * 0.8) * 0.22),
};
mkdirSync('public/sounds', { recursive: true });
for (const [k, s] of Object.entries(sounds)) writeFileSync(`public/sounds/${k}.wav`, wav(s));
writeFileSync('public/sounds/LICENSE.txt', 'These six sounds were synthesised by scripts/make-sounds.mjs for this app and are dedicated to the public domain under CC0 1.0 (https://creativecommons.org/publicdomain/zero/1.0/).\n');
console.log('sounds written');
